var response = await client.Carts.AddCartItemAsync(new Dictionary<string, object?>
{
    ["product_id"] = 101, ["quantity"] = 1, ["customer_id"] = 45, ["session_id"] = "cart-7f3a9c2e1b",
    ["shipping_address"] = new Dictionary<string, object?> { ["first_name"] = "Alex", ["last_name"] = "Taylor",
        ["address_line1"] = "1 Example Street", ["address_line2"] = "", ["city"] = "Sydney", ["post_code"] = "2000",
        ["phone"] = "", ["mobile"] = "", ["fax"] = "", ["email"] = "alex.taylor@example.com", ["country_code"] = "AU", ["state_code"] = "NSW" },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
