foreach (var item in ((IReadOnlyList<object?>)cart["items"]!).Cast<IReadOnlyDictionary<string, object?>>())
{
    var product = (IReadOnlyDictionary<string, object?>)item["product"]!;
    Console.WriteLine($"{item["id"]} {product["sku"]} {item["quantity"]}");
}
var totals = (IReadOnlyDictionary<string, object?>)cart["totals"]!;
var shipping = (IReadOnlyDictionary<string, object?>)cart["shipping"]!;
